<template><div v-if="show" data-testid="change-cover-modal" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"><form @submit.prevent="save" class="bg-white rounded-2xl p-6 w-full max-w-md"><h3 class="font-bold mb-4">Ganti Cover</h3><input data-testid="cover-input" type="file" accept="image/*" @change="file=$event.target.files?.[0]"/><div class="mt-5 flex justify-end gap-3"><button type="button" @click="$emit('close')">Batal</button><button class="px-4 py-2 bg-indigo-600 text-white rounded-lg">Simpan</button></div></form></div></template><script setup>import {ref} from 'vue';import {changeCover} from '../api/aucationApi';const p=defineProps({show:Boolean,aucation:Object});const e=defineEmits(['close','saved']);const file=ref(null);async function save(){if(!file.value)return;e('saved',await changeCover(p.aucation.id,file.value));e('close')}</script>
